def investigate(context, acquire):
    history = acquire("history")

    def simulate(actions, put_op, channel_type, trigger):
        committed = {}
        main_tx = None
        other_tx = None
        total_main = 0
        total_other = 0
        last_changes_main = 0

        def eff(conn):
            tx = main_tx if conn == 'main' else other_tx
            if tx is None:
                return dict(committed)
            e = dict(committed)
            for k, v in tx.items():
                if v is None:
                    if k in e:
                        del e[k]
                else:
                    e[k] = v
            return e

        def write(conn, key, value, is_delete):
            nonlocal committed, main_tx, other_tx, total_main, total_other, last_changes_main
            if conn == 'main':
                if main_tx is not None:
                    main_tx[key] = None if is_delete else value
                else:
                    if is_delete:
                        if key in committed:
                            del committed[key]
                    else:
                        committed[key] = value
            else:
                if other_tx is not None:
                    other_tx[key] = None if is_delete else value
                else:
                    if is_delete:
                        if key in committed:
                            del committed[key]
                    else:
                        committed[key] = value

        def count(conn, n):
            nonlocal total_main, total_other, last_changes_main
            if conn == 'main':
                total_main += n
                last_changes_main = n
            else:
                total_other += n

        for action in actions:
            op = action.get('op')
            conn = action.get('connection', 'main')
            if op == 'put':
                key = action['key']
                value = action['value']
                e = eff(conn)
                exists = key in e
                if put_op == 'ignore':
                    if exists:
                        count(conn, 0)
                    else:
                        write(conn, key, value, False)
                        count(conn, 1)
                        if trigger:
                            count(conn, 1)
                else:
                    write(conn, key, value, False)
                    count(conn, 1)
                    if trigger:
                        count(conn, 1)
            elif op == 'update':
                key = action['key']
                value = action['value']
                e = eff(conn)
                if key in e:
                    write(conn, key, value, False)
                    count(conn, 1)
                else:
                    count(conn, 0)
            elif op == 'delete':
                key = action['key']
                e = eff(conn)
                if key in e:
                    write(conn, key, None, True)
                    count(conn, 1)
                else:
                    count(conn, 0)
            elif op == 'begin':
                if conn == 'main':
                    main_tx = {}
                else:
                    other_tx = {}
            elif op == 'commit':
                if conn == 'main':
                    if main_tx is not None:
                        for k, v in main_tx.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        main_tx = None
                else:
                    if other_tx is not None:
                        for k, v in other_tx.items():
                            if v is None:
                                if k in committed:
                                    del committed[k]
                            else:
                                committed[k] = v
                        other_tx = None
            elif op == 'rollback':
                if conn == 'main':
                    main_tx = None
                else:
                    other_tx = None

        if channel_type == 'changes':
            channel = last_changes_main
        elif channel_type == 'total_main':
            channel = total_main
        else:
            channel = total_main + total_other

        return channel, len(committed), sum(committed.values())

    put_ops = ['ignore', 'replace', 'upsert']
    channel_types = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    consistent = []
    for put_op in put_ops:
        for channel_type in channel_types:
            for trigger in triggers:
                ok = True
                for receipt in history:
                    ch, cc, cs = simulate(receipt['actions'], put_op, channel_type, trigger)
                    obs = receipt['observed']
                    if ch != obs['channel'] or cc != obs['committed_count'] or cs != obs['committed_sum']:
                        ok = False
                        break
                if ok:
                    consistent.append((put_op, channel_type, trigger))

    if not consistent:
        return {"value": None, "unresolved": True}

    goal = context['goal']
    actions = context['actions']
    results = set()
    for put_op, channel_type, trigger in consistent:
        ch, cc, cs = simulate(actions, put_op, channel_type, trigger)
        if goal == 'channel':
            results.add(ch)
        elif goal == 'committed_count':
            results.add(cc)
        elif goal == 'committed_sum':
            results.add(cs)

    if len(results) == 1:
        return {"value": list(results)[0], "unresolved": False}
    return {"value": None, "unresolved": True}
